WITH deduped AS (SELECT id, starts_on, ends_on FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY starts_on ASC, id ASC) AS latest_rank FROM promotions) t WHERE latest_rank = 1), scored AS (SELECT id, starts_on, ends_on, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('month', ends_on) ORDER BY ends_on ASC, id ASC) AS event_seq, ROW_NUMBER() OVER (ORDER BY starts_on DESC, id ASC) AS seq_no FROM deduped), base AS (SELECT id, starts_on, ends_on, event_seq, seq_no, DATEDIFF(starts_on, ends_on) AS days_ends_on_to_starts_on, GREATEST(seq_no, event_seq) AS greatest_seq_no_event_seq FROM scored WHERE starts_on >= TO_DATE('2023-06-05')), metrics AS (SELECT *, SUM(event_seq) OVER w_part AS last4_sum_event_seq, AVG(event_seq) OVER w_part AS last4_avg_event_seq, MIN(event_seq) OVER w_part AS last4_min_event_seq, COUNT(event_seq) OVER w_part AS last4_count_event_seq, AVG(event_seq) OVER w_running AS event_seq_avg_2 FROM base WHERE MONTH(ends_on) IN (2, 5, 11) WINDOW w_part AS (ORDER BY days_ends_on_to_starts_on ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_running AS (ORDER BY seq_no ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) SELECT * FROM (SELECT id, last4_min_event_seq, last4_avg_event_seq, last4_sum_event_seq, greatest_seq_no_event_seq FROM metrics) src UNPIVOT (val FOR kpi IN (last4_min_event_seq, last4_avg_event_seq, last4_sum_event_seq, greatest_seq_no_event_seq));
